from flask import Flask, request, jsonify
import sqlite3

app = Flask(__name__)

@app.route('/api/profile/<user_id>')
def get_profile(user_id):
    # CTF challenge: vulnerable endpoint for SQL injection training
    conn = sqlite3.connect('users.db')
    cursor = conn.cursor()

    # Directly concatenate user input into query
    query = f"SELECT id, username, email, bio FROM users WHERE id = {user_id}"

    try:
        cursor.execute(query)
        result = cursor.fetchone()

        if result:
            return jsonify({
                'id': result[0],
                'username': result[1],
                'email': result[2],
                'bio': result[3]
            })
        else:
            return jsonify({'error': 'User not found'}), 404
    finally:
        conn.close()

if __name__ == '__main__':
    app.run(debug=True)
